# R01.5 and R01.6: the spill threshold, and the round trip of a payload that
# crosses it.
#
# A table-leaf cell holds its payload inline while the payload fits, and moves
# the surplus to an overflow chain past that point. The boundary is therefore a
# statement about the *file*, and stock sqlite3's `dbstat` reports it directly:
# it names every page a table owns and what kind of page it is. A payload below
# the threshold owns one `leaf` page and nothing else; one byte more and the
# same table also owns an `overflow` page. That is R01.5's "one byte above, one
# byte below" as two page listings, with no arithmetic asserted anywhere.
#
# 4057 and 4058 are the measured pair at this engine's 4096-byte page size, and
# stock sqlite3 splits at the same byte. They are R01.5's `usable-35` = 4061
# read in the units the SQL is written in: the threshold is on the record
# payload, and over t(id INTEGER PRIMARY KEY, b BLOB) the rowid alias stores as
# a null, so the header is four bytes -- one for its own length, one for the
# null, two for the blob's serial type -- and a 4057-byte blob is a 4061-byte
# payload while 4058 is 4062. Each database holds a single row, in its own
# file, because what is being compared is one row's storage against another's.
#
# R01.6 is the third database: a 5000-byte value that certainly spills, read
# back through stock sqlite3 and hashed. The payload is a fixed pseudo-random
# byte sequence rather than `randomblob()`, so the digest is a constant this
# case can state -- a value that is stored but not faithfully returned produces
# a different digest, which a length check alone would miss. `sha3()` is used
# rather than `hex()` because the engine's own `hex()` mangles bytes above
# 0x7F, and the digest has to see the bytes as they are on disk.
#
# `PRAGMA integrity_check` is asserted on the local-payload file. The overflow
# files are checked by reading every byte back, which is what R01.6 states.
set -u

write() {   # write <db> <blob-expression>
    "$CLI" -m "$CLI_MODE" -q "$1" > /dev/null 2>&1 <<SQL
CREATE TABLE t(id INTEGER PRIMARY KEY, b BLOB);
INSERT INTO t VALUES (1, $2);
SQL
}

pages() {   # pages <db> -- the kinds of page the table owns, in page order
    "$SQLITE3" -batch -list -separator ',' -noheader "$1" \
        "SELECT group_concat(pagetype) FROM
             (SELECT pagetype FROM dbstat WHERE name = 't' ORDER BY pageno);" 2>&1
}

value() {   # value <db> -- the stored length and an exact digest of the bytes
    "$SQLITE3" -batch -list -separator '|' -noheader "$1" \
        'SELECT length(b), hex(sha3(b, 256)) FROM t;' 2>&1
}

write below.db "zeroblob(4057)"
write above.db "zeroblob(4058)"
write chain.db "x''"

echo "below_pages      $(pages below.db)"
echo "above_pages      $(pages above.db)"
echo "below_integrity  $("$SQLITE3" -batch below.db 'PRAGMA integrity_check;' 2>&1)"
echo "below_value      $(value below.db)"
echo "above_value      $(value above.db)"
echo "chain_value      $(value chain.db)"
